package pl.zagranietyper.repository;
import org.junit.jupiter.api.Test;import pl.zagranietyper.model.FootballFixtureEventsSnapshot;import static org.junit.jupiter.api.Assertions.*;
class FootballFixtureEventsRepositoryTest {@Test void failedOrEmptyNeverOverwritesComplete(){assertFalse(FootballFixtureEventsRepository.shouldReplace(FootballFixtureEventsSnapshot.FetchStatus.COMPLETE,FootballFixtureEventsSnapshot.FetchStatus.FETCH_FAILED));assertFalse(FootballFixtureEventsRepository.shouldReplace(FootballFixtureEventsSnapshot.FetchStatus.COMPLETE,FootballFixtureEventsSnapshot.FetchStatus.UNSUPPORTED_OR_EMPTY));}@Test void completeReingestionIsIdempotentlyReplaceable(){assertTrue(FootballFixtureEventsRepository.shouldReplace(FootballFixtureEventsSnapshot.FetchStatus.COMPLETE,FootballFixtureEventsSnapshot.FetchStatus.COMPLETE));assertTrue(FootballFixtureEventsRepository.shouldReplace(FootballFixtureEventsSnapshot.FetchStatus.API_ERROR,FootballFixtureEventsSnapshot.FetchStatus.COMPLETE));}}
